// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testFuzz_property(address caller, uint256 ndcIndex, uint256 amount) public {
        // The MANAGER role is checked against c's lrtConfig; no one is ever granted it,
        // so every fuzzed caller is a non-manager.
        vm.assume(caller != address(0));

        // Drive the guarded entry transferAssetToNodeDelegator first.
        vm.prank(caller);
        try c.transferAssetToNodeDelegator(ndcIndex, address(0x1), amount) { } catch { }

        // Same guard protects pause(): a non-manager caller must either be reverted
        // or leave the pause state untouched.
        bool ok;
        vm.prank(caller);
        try c.pause() { ok = true; } catch { ok = false; }

        // General rule: without the MANAGER role, no caller can flip c into the
        // paused state — the call must revert or paused() must remain false.
        assertTrue(!ok || !c.paused());
    }
}
